#!/usr/bin/env python3
"""incrback.py -- minimal content-addressed incremental backup tool (stdlib only).

Commands:
    incrback.py snap SRC STORE       Create a new snapshot of SRC in STORE.
    incrback.py restore STORE N TGT  Materialize snapshot N into directory TGT.
    incrback.py gc STORE             Delete blobs not referenced by any snapshot.
    incrback.py diff STORE A B       Print added/modified/deleted paths A -> B.
"""

import hashlib
import json
import os
import shutil
import sys

CHUNK = 1024 * 1024


# ---------------------------------------------------------------- helpers

def sha256_file(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        while True:
            chunk = f.read(CHUNK)
            if not chunk:
                break
            h.update(chunk)
    return h.hexdigest()


def objects_dir(store):
    return os.path.join(store, "objects")


def snapshots_dir(store):
    return os.path.join(store, "snapshots")


def list_snapshots(store):
    sdir = snapshots_dir(store)
    if not os.path.isdir(sdir):
        return []
    nums = []
    for name in os.listdir(sdir):
        if name.endswith(".json") and name[:-5].isdigit():
            nums.append(int(name[:-5]))
    return sorted(nums)


def next_snapshot_number(store):
    snaps = list_snapshots(store)
    return (snaps[-1] + 1) if snaps else 1


def snapshot_path(store, n):
    return os.path.join(snapshots_dir(store), "%d.json" % int(n))


def load_snapshot(store, n):
    p = snapshot_path(store, n)
    if not os.path.isfile(p):
        sys.exit("error: no such snapshot: %d" % n)
    with open(p, "r", encoding="utf-8") as f:
        return json.load(f)


def store_blob(store, src_path, digest):
    """Copy src_path's bytes into STORE/objects/<digest> unless already present."""
    dst = os.path.join(objects_dir(store), digest)
    if os.path.exists(dst):
        return dst
    tmp = dst + ".tmp.%d" % os.getpid()
    try:
        with open(src_path, "rb") as fi, open(tmp, "wb") as fo:
            while True:
                chunk = fi.read(CHUNK)
                if not chunk:
                    break
                fo.write(chunk)
        # Dedup race-safe: another writer may have finished first.
        if os.path.exists(dst):
            os.remove(tmp)
        else:
            os.replace(tmp, dst)
    finally:
        if os.path.exists(tmp):
            try:
                os.remove(tmp)
            except OSError:
                pass
    return dst


def iter_files(root):
    """Yield relative paths of regular files under root, POSIX-style separators."""
    root = os.path.abspath(root)
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames.sort()
        for name in sorted(filenames):
            full = os.path.join(dirpath, name)
            rel = os.path.relpath(full, root).replace(os.sep, "/")
            if os.path.isfile(full):  # skips broken symlinks etc.
                yield rel, full


# ---------------------------------------------------------------- commands

def cmd_snap(src, store):
    src = os.path.abspath(src)
    if not os.path.isdir(src):
        sys.exit("error: source is not a directory: %s" % src)
    os.makedirs(objects_dir(store), exist_ok=True)
    os.makedirs(snapshots_dir(store), exist_ok=True)

    files = {}
    for rel, full in iter_files(src):
        digest = sha256_file(full)
        store_blob(store, full, digest)
        st = os.stat(full)
        files[rel] = {
            "sha256": digest,
            "size": st.st_size,
            "mode": st.st_mode & 0o777,
        }

    n = next_snapshot_number(store)
    doc = {"version": 1, "source": src, "files": files}
    tmp = snapshot_path(store, n) + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(doc, f, indent=2, sort_keys=True)
    os.replace(tmp, snapshot_path(store, n))
    print("snapshot %d: %d files" % (n, len(files)))
    return n


def cmd_restore(store, n, target):
    doc = load_snapshot(store, n)
    target = os.path.abspath(target)
    os.makedirs(target, exist_ok=True)
    count = 0
    for rel, meta in sorted(doc["files"].items()):
        blob = os.path.join(objects_dir(store), meta["sha256"])
        if not os.path.isfile(blob):
            sys.exit("error: missing blob %s (corrupted store?)" % meta["sha256"])
        dest = os.path.join(target, *rel.split("/"))
        os.makedirs(os.path.dirname(dest) or target, exist_ok=True)
        shutil.copyfile(blob, dest)
        os.chmod(dest, meta.get("mode", 0o644))
        count += 1
    print("restored snapshot %d: %d files into %s" % (n, count, target))


def cmd_gc(store):
    referenced = set()
    for n in list_snapshots(store):
        doc = load_snapshot(store, n)
        for meta in doc["files"].values():
            referenced.add(meta["sha256"])
    removed = 0
    odir = objects_dir(store)
    if os.path.isdir(odir):
        for name in sorted(os.listdir(odir)):
            full = os.path.join(odir, name)
            if os.path.isfile(full) and name not in referenced:
                os.remove(full)
                removed += 1
    print("gc: deleted %d unreferenced blobs" % removed)
    return removed


def cmd_diff(store, a, b):
    da = load_snapshot(store, a)["files"]
    db = load_snapshot(store, b)["files"]
    added = sorted(set(db) - set(da))
    deleted = sorted(set(da) - set(db))
    modified = sorted(p for p in set(da) & set(db) if da[p]["sha256"] != db[p]["sha256"])

    def show(label, paths):
        for p in paths:
            print("%s %s" % (label, p))

    show("+", added)
    show("-", deleted)
    show("~", modified)
    print("added %d, modified %d, deleted %d" % (len(added), len(modified), len(deleted)))


USAGE = __doc__


def main(argv):
    args = argv[1:]
    if len(args) == 3 and args[0] == "snap":
        cmd_snap(args[1], args[2])
    elif len(args) == 4 and args[0] == "restore":
        cmd_restore(args[1], int(args[2]), args[3])
    elif len(args) == 2 and args[0] == "gc":
        cmd_gc(args[1])
    elif len(args) == 4 and args[0] == "diff":
        cmd_diff(args[1], int(args[2]), int(args[3]))
    else:
        sys.exit(USAGE.strip())


if __name__ == "__main__":
    main(sys.argv)

